-- FOXSCAN tenant isolation, workflow, payment and audit schema. Apply with Supabase CLI.
create extension if not exists pgcrypto;
create type public.app_role as enum ('ADMIN','CLIENT','CONSULTANT','MANUFACTURER','CONTRACTOR');
create type public.project_status as enum ('DRAFT','ACTIVE','ON_HOLD','COMPLETED','CANCELLED');
create type public.activity_status as enum ('NOT_STARTED','IN_PROGRESS','SUBMITTED','APPROVED','PAID','ON_HOLD');
create type public.workflow_state as enum ('CONTRACTOR','MANUFACTURER','CONSULTANT','CLIENT','PAID','REWORK');
create table public.tenants(id uuid primary key default gen_random_uuid(),name text not null,type text not null check(type in ('SOCIETY','CONSULTANT','MANUFACTURER','CONTRACTOR')),gstin text,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,tenant_id uuid not null references public.tenants(id),name text not null,phone text,role public.app_role not null,active boolean not null default true,created_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),name text not null,address text not null,scope text not null,buildings int not null check(buildings>0),area_sqft numeric(14,2) not null check(area_sqft>=0),contract_value numeric(16,2) not null check(contract_value>=0),start_date date not null,end_date date not null,status public.project_status not null default 'DRAFT',created_at timestamptz not null default now(),check(end_date>=start_date));
create table public.project_members(project_id uuid references public.projects(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,role public.app_role not null,primary key(project_id,user_id));
create table public.activities(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,name text not null,description text,sequence int not null,planned_start date not null,planned_end date not null,actual_start date,actual_end date,progress numeric(5,2) not null default 0 check(progress between 0 and 100),status public.activity_status not null default 'NOT_STARTED',payment_mode text not null check(payment_mode in ('PERCENTAGE','FIXED','MILESTONE','RA_BILL')),payment_value numeric(16,2) not null check(payment_value>=0),retention_pct numeric(5,2) not null default 0 check(retention_pct between 0 and 100),gst_pct numeric(5,2) not null default 0 check(gst_pct between 0 and 100),unique(project_id,sequence));
create table public.activity_dependencies(activity_id uuid references public.activities(id) on delete cascade,depends_on_id uuid references public.activities(id) on delete cascade,primary key(activity_id,depends_on_id),check(activity_id<>depends_on_id));
create table public.stages(id uuid primary key default gen_random_uuid(),activity_id uuid not null references public.activities(id) on delete cascade,state public.workflow_state not null,raised_at timestamptz not null default now(),due_at timestamptz not null,submitted_by uuid not null references public.profiles(id),amount_due numeric(16,2) not null default 0,check(due_at>=raised_at));
create table public.stage_decisions(id uuid primary key default gen_random_uuid(),stage_id uuid not null references public.stages(id) on delete cascade,actor_id uuid not null references public.profiles(id),role public.app_role not null,decision text not null check(decision in ('RAISED','APPROVED','RETURNED','PAYMENT_RELEASED')),note text,created_at timestamptz not null default now());
create table public.stage_comments(id uuid primary key default gen_random_uuid(),stage_id uuid not null references public.stages(id) on delete cascade,actor_id uuid not null references public.profiles(id),body text not null,kind text not null check(kind in ('COMMENT','SUGGESTION','RETURN_REASON')),created_at timestamptz not null default now());
create table public.invoices(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),activity_id uuid not null references public.activities(id),stage_id uuid not null unique references public.stages(id),invoice_number text not null,subtotal numeric(16,2) not null,cgst numeric(16,2) not null default 0,sgst numeric(16,2) not null default 0,igst numeric(16,2) not null default 0,retention numeric(16,2) not null default 0,total numeric(16,2) not null,status text not null check(status in ('UPLOADED','MATCHED','APPROVED','PAID')),payment_reference text,unique(project_id,invoice_number));
create table public.site_updates(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,activity_id uuid references public.activities(id),author_id uuid not null references public.profiles(id),logged_at timestamptz not null default now(),weather text not null,manpower int not null check(manpower>=0),equipment text not null default '',work_done text not null,issues text,latitude numeric(9,6),longitude numeric(9,6),voice_url text,important boolean not null default false);
create table public.delays(id uuid primary key default gen_random_uuid(),activity_id uuid not null references public.activities(id) on delete cascade,reason text not null check(reason in ('WEATHER','MATERIAL_SHORTAGE','MANPOWER','SOCIETY_ACCESS','SCOPE_CHANGE','OTHER')),impact_days int not null check(impact_days>=0),owner_id uuid not null references public.profiles(id),mitigation_plan text not null,target_close date not null,resolved_at timestamptz);
create table public.documents(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,name text not null,type text not null,version int not null default 1,storage_path text not null,uploaded_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(project_id,name,version));
create table public.audit_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),actor_id uuid references public.profiles(id),action text not null,entity text not null,entity_id uuid,previous jsonb,next jsonb,ip inet,device text,created_at timestamptz not null default now(),immutable_hash text not null);
create index on public.projects(tenant_id,status); create index on public.activities(project_id,sequence); create index on public.stages(activity_id,state,due_at); create index on public.audit_events(tenant_id,created_at desc);
alter table public.tenants enable row level security; alter table public.profiles enable row level security; alter table public.projects enable row level security; alter table public.project_members enable row level security; alter table public.activities enable row level security; alter table public.stages enable row level security; alter table public.stage_decisions enable row level security; alter table public.stage_comments enable row level security; alter table public.invoices enable row level security; alter table public.site_updates enable row level security; alter table public.delays enable row level security; alter table public.documents enable row level security; alter table public.audit_events enable row level security;
create function public.can_access_project(target uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from project_members where project_id=target and user_id=auth.uid()) or exists(select 1 from profiles where id=auth.uid() and role='ADMIN')$$;
create policy "tenant users read profile" on public.profiles for select using (tenant_id=(select tenant_id from public.profiles where id=auth.uid()) or id=auth.uid());
create policy "project member access" on public.projects for all using (public.can_access_project(id)) with check (public.can_access_project(id));
create policy "member access" on public.project_members for select using (public.can_access_project(project_id));
create policy "activity access" on public.activities for all using (public.can_access_project(project_id)) with check (public.can_access_project(project_id));
create policy "stage access" on public.stages for all using (public.can_access_project((select project_id from public.activities where id=activity_id))) with check (public.can_access_project((select project_id from public.activities where id=activity_id)));
create policy "decision access" on public.stage_decisions for all using (exists(select 1 from public.stages s join public.activities a on a.id=s.activity_id where s.id=stage_id and public.can_access_project(a.project_id))) with check (true);
create policy "comment access" on public.stage_comments for all using (exists(select 1 from public.stages s join public.activities a on a.id=s.activity_id where s.id=stage_id and public.can_access_project(a.project_id))) with check (true);
create policy "invoice access" on public.invoices for all using (public.can_access_project(project_id)) with check (public.can_access_project(project_id));
create policy "site access" on public.site_updates for all using (public.can_access_project(project_id)) with check (public.can_access_project(project_id));
create policy "delay access" on public.delays for all using (public.can_access_project((select project_id from public.activities where id=activity_id))) with check (true);
create policy "document access" on public.documents for all using (public.can_access_project(project_id)) with check (public.can_access_project(project_id));
create policy "audit read only" on public.audit_events for select using (tenant_id=(select tenant_id from public.profiles where id=auth.uid()) or exists(select 1 from public.profiles where id=auth.uid() and role='ADMIN'));
revoke insert,update,delete on public.audit_events from anon,authenticated;
